import React, { useEffect, useRef } from 'react';
import './NiftyChart.css';

const NiftyChart = () => {
  const containerRef = useRef();

  useEffect(() => {
    // Clear previous widget if it exists (for React 18 strict mode double-mounts)
    if (containerRef.current) {
        containerRef.current.innerHTML = '';

        const script = document.createElement('script');
        script.type = 'text/javascript';
        script.src = 'https://s3.tradingview.com/external-embedding/embed-widget-mini-symbol-overview.js';
        script.async = true;

        const config = document.createElement('script');
        config.type = 'application/json';
        config.innerHTML = JSON.stringify({
          "symbol": "NSE:NIFTY",
          "width": "100%",
          "height": "350",
          "locale": "en",
          "dateRange": "1M",
          "colorTheme": "light",
          "trendLineColor": "#14C4B5",
          "underLineColor": "rgba(20, 196, 181, 0.3)",
          "underLineBottomColor": "rgba(20, 196, 181, 0)",
          "isTransparent": false,
          "autosize": false,
          "largeChartUrl": ""
        });

        containerRef.current.appendChild(config);
        containerRef.current.appendChild(script);
    }
  }, []);

  return (
    <div className="chart-widget-block">
      <h3 className="chart-title">Market Overview</h3>
      <div ref={containerRef} className="chart-embed"></div>
    </div>
  );
};

export default NiftyChart;
